export default {"defaultProject":{"format":"riscv-assembly-lab-project","version":1,"id":"default-project","name":"Register addition","kind":"asm","source":"li t0, 7\nli t1, 5\nadd t2, t0, t1\n","inputs":{},"data":[],"memory":"data","result":"t2","pins":["t0","t1","t2"]},"examples":[{"format":"riscv-assembly-lab-project","version":1,"id":"example-addition","name":"Add two register values","kind":"asm","source":"li t0, 7\nli t1, 5\nadd t2, t0, t1\n","inputs":{},"data":[],"memory":"data","result":"t2","pins":["t0","t1","t2"],"origin":{"id":"addition","title":"Add two register values","activity":"example"}},{"format":"riscv-assembly-lab-project","version":1,"id":"example-sum-array","name":"Walk an array without crossing its end","kind":"asm","source":"li t0, 4\nla t1, lesson_data\nli t2, 0\nli t3, 0\nagain:\nbgeu t3, t0, done\nlwu t4, 0(t1)\nadd t2, t2, t4\naddi t1, t1, 4\naddi t3, t3, 1\nj again\ndone:\n","inputs":{},"data":[10,0,0,0,20,0,0,0,30,0,0,0,40,0,0,0],"memory":"data","result":"t2","pins":["t0","t1","t2","t3","t4"],"origin":{"id":"sum-array","title":"Walk an array without crossing its end","activity":"example"},"memoryLabels":[{"offset":0,"label":"supplied data begins"}]},{"format":"riscv-assembly-lab-project","version":1,"id":"example-stack-frames","name":"Keep values in a stack frame","kind":"asm","source":"li s0, 73\nmv t0, sp\naddi sp, sp, -64\nsd s0, 0(sp)\nli s0, 9\nld t1, 0(sp)\nsub t2, t0, sp\n","inputs":{},"data":[],"memory":"stack","result":"t1","pins":["s0","t1","t2","sp"],"origin":{"id":"stack-frames","title":"Keep values in a stack frame","activity":"example"},"memoryLabels":[{"offset":0,"label":"saved s0, eight bytes"}]},{"format":"riscv-assembly-lab-project","version":1,"id":"example-c-return-values","name":"Follow a C return value","kind":"c","source":"unsigned long lesson(unsigned long a, unsigned long b) {\n    unsigned long charge = a * b;\n    return charge + 7;\n}\n","inputs":{"a0":"0x0000000000000006","a1":"0x0000000000000004"},"data":[],"memory":"data","result":"a0","pins":["a0","sp"],"origin":{"id":"c-return-values","title":"Follow a C return value","activity":"example"}},{"format":"riscv-assembly-lab-project","version":1,"id":"example-system-calls","name":"Ask xv6 to write bytes","kind":"asm","source":"li a0, 1\nla a1, lesson_data\nli a2, 5\nli a7, 16\necall\nmv t2, a0\n","inputs":{},"data":[116,114,105,112,10],"memory":"data","result":"t2","pins":["a0","a1","t2"],"origin":{"id":"system-calls","title":"Ask xv6 to write bytes","activity":"example"},"memoryLabels":[{"offset":0,"label":"message bytes"}]},{"format":"riscv-assembly-lab-project","version":1,"id":"example-hello-world","name":"Hello World","kind":"program","source":"# Change the message, then choose Build & Run.\n.section .rodata\nmessage:\n    .ascii \"Hello, RISC-V!\\n\"\n.equ message_length, . - message\n\n.text\n.global _start\n_start:\n    # write(1, message, message_length)\n    li a0, 1                  # 1 = standard output\n    la a1, message            # address of the bytes to write\n    li a2, message_length     # number of bytes\n    li a7, 16                 # xv6 system call: write\n    ecall                     # ask xv6 to perform it\n\n    # exit(0)\n    li a0, 0                  # exit status\n    li a7, 2                  # xv6 system call: exit\n    ecall\n","inputs":{},"data":[],"memory":"data","result":"t2","pins":["t0","t1","t2"]},{"format":"riscv-assembly-lab-project","version":1,"id":"example-complete-counts","name":"Complete program: combine two counts","kind":"program","source":"# Copyright © 2026 Christopher Snow\n.text\n.global _start\n_start:\n    la t0, counts\n    ld a0, 0(t0)\n    ld a1, 8(t0)\n    call combine\n    mv s0, a0\n    li a0, 0\n    li a7, 2\n    ecall\n\ncombine:\n    add a0, a0, a1\n    ret\n\n.data\n.balign 8\n.global counts\ncounts: .quad 19, 23\n    .zero 48\n","inputs":{},"data":[],"memory":"data","result":"s0","pins":["a0","a1","s0"]},{"format":"riscv-assembly-lab-project","version":1,"id":"example-fresh-counts","name":"Complete program: compare two counts","kind":"program","source":"# Copyright © 2026 Christopher Snow\n.text\n.global _start\n_start:\n    la t0, counts\n    ld a0, 0(t0)\n    ld a1, 8(t0)\n    call combine\n    mv s0, a0\n    li a0, 0\n    li a7, 2\n    ecall\n\ncombine:\n    add a0, a0, a1\n    ret\n\n.data\n.balign 8\n.global counts\ncounts: .quad 31, 17\n    .zero 48\n","inputs":{},"data":[],"memory":"data","result":"s0","pins":["a0","a1","s0"]}],"copy":{"title":"RISC-V playground","intro":"Write and run your own code in the course workbench. Open Tools for inspection, setup and projects.","links":{"homeLabel":"Open the playground","homeDescription":"Use the course workbench for your own projects. Each project keeps its source and starting setup together.","guideTitle":"Work on an independent project","guideParagraphs":["Use the lesson’s example and optional exercise for guided work. To keep an independent experiment, open Tools → Projects and choose Save a copy. The project opens in the same editor with its own source and starting setup.","A copy of an exercise uses the selected case’s inputs and data. Project edits keep the lesson draft unchanged. Choose Return to lesson to restore the example or exercise you left.","Open the playground from the course overview to work on independent projects. In a lesson, use Tools → Projects to keep working in the same editor."]},"projectTypes":[{"id":"asm","label":"Assembly fragment","description":"Write the instructions you want to investigate. Supplied code starts the program, captures registers and exits.","sourceHelp":"Write assembly instructions. View complete program shows the supplied entry, reporting and exit code.","entryHelp":"The lab supplies entry, register capture and exit code around your assembly fragment.","completeSourceDescription":"This is your fragment inside the supplied entry, capture and exit code. The supplied code prepares the listed inputs and records registers and memory before printing the report."},{"id":"c","label":"C function","description":"Write a function named lesson. The supplied caller passes its arguments and captures its result.","signature":"long lesson(long a, long b)","sourceHelp":"Define lesson with two long arguments. Starting registers a0 and a1 supply the arguments; a0 receives the returned value.","entryHelp":"The lab supplies a caller that passes the starting arguments to lesson, captures registers and exits.","completeSourceDescription":"This view contains your C function and its supplied assembly caller. The caller prepares the listed arguments, captures registers and memory, prints the report and exits."},{"id":"program","label":"Complete assembly program","description":"Define _start, the program’s entry label. Your source controls initialisation, data and exit.","sourceHelp":"Define _start and include your program’s exit code. Start stepping or Start debugging to inspect registers while it runs.","entryHelp":"Your program defines _start and supplies its own initialisation, data and exit code. No entry or reporting code is added.","completeSourceDescription":"This is your complete assembly source, used unchanged for the build. Its entry, initialisation, data and exit belong to the program. No final register report is added."}],"labels":{"projects":"Projects","projectName":"Project name","newProject":"New project","projectType":"Project type","createProject":"Create project","cancel":"Cancel","example":"Example","chooseExample":"Choose an example","openExample":"Open example","saveCopy":"Save a copy","projectActions":"Project actions","import":"Import file","importAs":"Import as","openImportedProject":"Open imported project","export":"Export project","downloadSource":"Download source","delete":"Delete project","undoDelete":"Undo delete","setup":"Starting setup","registers":"Starting registers","data":"Data bytes at lesson_data","memoryView":"Memory view","dataView":"Data bytes","stackView":"Stack bytes","highlight":"Highlighted register","applySetup":"Apply setup","restoreLoaded":"Restore loaded source","undoRestore":"Undo restore","allRegisters":"All integer registers","lastPausedPC":"Last paused PC","editorWidth":"Editor width","resizePanes":"Resize editor and inspector","help":"Using the playground","sourceLesson":"Back to source lesson","mainAssembly":"main.s","mainC":"main.c","examples":"Examples","renameProject":"Rename project","observation":"Observation","tools":"Tools","returnToLesson":"Return to lesson","lessonDraft":"Lesson draft","projectNotes":"Project notes"},"setup":{"intro":"Set the values supplied before your code starts. Apply setup ends the current run; the next build starts a fresh machine.","registerHelp":"Use one assignment per line, such as t0 = 7. Decimal is the default; use 0x for hexadecimal or 0b for binary. Values must fit 64 bits.","reservedHelp":"The starting setup does not accept zero, sp, gp or tp. The supplied code prepares the stack pointer; zero always reads zero.","registerPlaceholder":"t0 = 7\nt1 = 5","dataHelp":"Use pairs of hexadecimal digits separated by spaces, such as 01 FF. Up to 64 bytes; remaining bytes start at zero.","dataPlaceholder":"01 02 03 04","memoryHelp":"Data shows 64 bytes from lesson_data. Stack shows 64 bytes from the observed stack pointer, sp.","highlightHelp":"Marks a register in the inspector. It does not change execution.","fullProgramHelp":"A complete assembly program supplies its own initialisation and data. Set those values in the source.","fullProgramMemoryHelp":"The Data view starts at lesson_data if your program defines that symbol. Otherwise it starts at the first loaded writable region, or the first code region if none is writable. Stack starts at the observed sp.","summary":{"zeroRegisters":"Working registers start at zero","presets":"Registers (unsigned decimal): {values}","moreRegisters":"; {count} more","dataBytes":"{count} supplied data bytes","zeroData":"64 zero data bytes","fullProgram":"Defined in source"},"lessonHelp":"Apply setup opens a project copy with these values. Your lesson draft and its starting setup stay unchanged."},"messages":{"saved":"Project saved in this browser.","tabOnly":"Project is tab-only. Export project to keep it.","setupApplied":"Setup applied. Build or start stepping for a fresh machine.","exampleOpened":"Example opened as a new project. Your other projects are kept.","projectOpened":"Project opened. Build or start stepping for a fresh machine.","copyCreated":"Project copied. Your original project is kept.","imported":"File opened as a new project. Your other projects are kept.","importFailed":"Could not import this file. Your current project is unchanged.","setupFailed":"Correct the setup entries, then apply them again. Your current setup is unchanged.","unsupportedVersion":"This project file uses an unsupported version.","invalidProject":"This file is not a valid RISC-V Assembly Lab project.","projectDeleted":"Project deleted. Undo delete recovers it.","deleteUndone":"Project restored.","transferOpened":"Lesson code and starting setup opened as a new project. Your lesson draft is unchanged.","transferFailed":"Could not open the transferred project. Your saved projects are unchanged.","programFinished":"Program finished. Inspect Output, or start stepping to capture register observations.","lastPause":"Last observed at a pause before the program finished. These are not exit register values.","notObserved":"Start stepping or Start debugging to observe this program’s registers.","lastPausedObservation":"Registers, memory and stack show the last pause before this program finished. They do not show the exit state.","noPausedObservation":"No paused observation was captured. Start stepping or Start debugging to inspect registers, memory and stack.","lessonRestored":"Lesson draft restored. Build or start stepping for a fresh machine.","lessonCopyCreated":"Project copy opened in this workspace. Your lesson draft is kept."},"help":[{"id":"workspace-views","title":"Source and execution","paragraphs":["The editor and run controls work the same way in lessons and independent projects. Open Tools when you need more inspection, starting setup or saved projects. Close Tools to concentrate on the code and its relevant results.","Program shows your current source inside its complete program. Expand a supplied section to inspect the setup, capture or reporting code. Your fragment stays editable in the editor.","Machine instructions shows the executable from your last successful build. Build again after editing the source. During stepping, PC marks the next instruction to execute.","Registers shows observations from execution. Pin useful registers, compare changed values, or choose All to see every integer register."]},{"id":"project-and-source","title":"Choose the source you want to write","paragraphs":["An assembly fragment is a group of instructions inside a supplied program. You can concentrate on those instructions; View complete program shows the entry, reporting and exit code around them.","A C project defines a function named lesson, such as long lesson(long a, long b). The supplied caller passes a0 and a1 as its arguments and captures the return value in a0. Do not add main, system headers or library calls.","A complete assembly program defines _start and includes its own exit code. Its registers and data come from its source and xv6, so the fragment’s starting-register and data controls do not apply."]},{"id":"run-and-observe","title":"Run and inspect","paragraphs":["Build & Run assembles and links your source, then runs it as an xv6 user process. C projects first compile their function with TinyCC. Every new run starts a fresh machine.","Start stepping pauses before your first machine instruction. Step instruction executes one machine instruction. A source line can expand into several machine instructions.","A breakpoint pauses before its instruction runs. Choose the numbered button beside an assembly instruction, then use Start debugging. Continue runs to a selected breakpoint or the end of your code. For C, select actual instruction addresses in Debugger; this compiler does not provide C source-line mappings.","Register and memory readings belong to the observation named beside them. Assembly fragments and C functions capture a report after their code. Complete programs can exit without that report: a last paused observation is not an exit state."]},{"id":"starting-values","title":"Supply starting values","paragraphs":["For fragments and C functions, Setup supplies register values before your source runs. Use assignments such as t0 = 7, one per line. Apply setup commits the entries and ends the current run. Editing the setup form alone does not change a paused machine.","Data bytes fills the area named lesson_data. Hexadecimal uses digits 0–9 and A–F; two hexadecimal digits describe one byte. Unspecified bytes start at zero.","Memory view chooses the 64-byte region shown in Memory. Data starts at lesson_data. Stack starts at the observed stack pointer, sp. The Stack tab and memory watches provide further observed readings."]},{"id":"keep-projects","title":"Keep your projects","paragraphs":["Source and setup save together in this browser when storage is available. Check the save message. A project saves your code and setup, not a running or paused machine.","Open Tools → Projects to open a saved project, choose an example, import a file or create a new project. Open example and Import file create new projects and keep your other work. Save a copy keeps the current source and setup in another project.","From a lesson, Save a copy opens an independent project in the same editor. The lesson draft stays available through Return to lesson. An exercise copy uses the selected case’s inputs and data.","Export project saves the source and setup in one JSON file. Download code saves only the source. Import file accepts project JSON, assembly source (.s or .asm), or C source (.c). Check Import as before opening a source file.","If storage is unavailable, you can keep working in this tab. Export project before leaving to keep that work. Delete project can be reversed with Undo delete."]},{"id":"environment","title":"Know the execution environment","paragraphs":["Programs target 64-bit RISC-V and run in xv6. Its system calls differ from Linux and teaching simulators. In this guest, write is system call 16 and exit is system call 2.","The playground supplies console output, but no console input. The guest does not provide floating-point process state. Stepping shows functional execution, not physical hardware timing."]}],"workspace":{"code":"Code","program":"Program","inspect":"Inspect","views":"Workspace view","source":"Program source","instructions":"Machine instructions","currentSource":"Current source · read-only","fragmentIntro":"Your code sits inside the supplied program. Expand the folded sections to inspect its setup and reporting code.","programIntro":"This is your complete source. The build uses it unchanged.","cIntro":"Your C function and its supplied assembly caller are separate source files. Build the program to inspect the compiled instructions.","cSource":"Your C function","cCaller":"Supplied assembly caller","parts":{"entry":"Entry","setup":"Supplied initialisation","user":"Your code","caller":"Call your C function","report":"Supplied capture, reporting and exit","data":"Starting data · lesson_data"},"lines":"lines","noBuild":"Build or start stepping to see the instructions in the executable.","buildNote":"Last successful build. PC marks the next instruction at the last pause. One assembly source line can produce several instructions.","stale":"Source changed. Instructions and observations still belong to the previous build. Build again to use your edits.","cMapping":"TinyCC does not provide C source-line mappings. This scope shows the compiled lesson function.","userInstructions":"Your instructions","allInstructions":"All instructions","scope":"Instruction scope","allScope":"All includes supplied setup, helper functions and reporting code.","filter":"Show registers","all":"All","pinned":"Pinned","changed":"Changed","filterHelp":"Pinned keeps chosen registers together. Changed compares values with the preceding observation. All shows every integer register.","emptyRegisters":"No registers match this view. Pin a register from All, or run or step to compare values.","pin":"Pin","unpin":"Unpin","changedMark":"Changed","pinMark":"Pinned","editCode":"Edit code","download":"Download complete program","noInstructions":"This build emitted no instructions in this scope.","pc":"PC","address":"Address","instruction":"Instruction","sourceLine":"Source line","setup":"Setup","help":"Help","cUserInstructions":"lesson function","cAllMapping":"TinyCC does not provide C source-line mappings. All includes compiled C and the supplied assembly.","jumpPc":"Jump to PC"}},"markup":"\u003csection class=\"project-tools\" aria-label=\"Project tools\">\u003clabel>Projects\u003cselect id=\"project-picker\" disabled>\u003c/select>\u003c/label>\u003cbutton id=\"new-project\" disabled>New project\u003c/button>\u003cdetails class=\"project-examples\">\u003csummary>Examples\u003c/summary>\u003cdiv>\u003clabel class=\"project-example-label\">Example\u003cselect id=\"project-example\">\u003coption value=\"example-addition\">Add two register values\u003c/option>\u003coption value=\"example-sum-array\">Walk an array without crossing its end\u003c/option>\u003coption value=\"example-stack-frames\">Keep values in a stack frame\u003c/option>\u003coption value=\"example-c-return-values\">Follow a C return value\u003c/option>\u003coption value=\"example-system-calls\">Ask xv6 to write bytes\u003c/option>\u003coption value=\"example-hello-world\">Hello World\u003c/option>\u003coption value=\"example-complete-counts\">Complete program: combine two counts\u003c/option>\u003coption value=\"example-fresh-counts\">Complete program: compare two counts\u003c/option>\u003c/select>\u003c/label>\u003cbutton id=\"open-example\" disabled>Open example\u003c/button>\u003c/div>\u003c/details>\u003cdetails class=\"project-actions\">\u003csummary>Project actions\u003c/summary>\u003cdiv>\u003clabel>Project name\u003cinput id=\"project-name\" maxlength=\"80\" value=\"Register addition\" autocomplete=\"off\">\u003c/label>\u003cbutton id=\"copy-project\">Save a copy\u003c/button>\u003cbutton id=\"import-file\">Import file\u003c/button>\u003cbutton id=\"export-project\">Export project\u003c/button>\u003cbutton id=\"delete-project\">Delete project\u003c/button>\u003c/div>\u003c/details>\u003cinput type=\"file\" id=\"project-file\" accept=\".json,.s,.asm,.c\" hidden>\u003c/section>\n\u003cdiv class=\"project-origin-row\">\u003cbutton id=\"undo-delete\" class=\"text-button\" hidden>Undo delete\u003c/button>\u003c/div>\u003cp id=\"project-message\" role=\"status\">\u003c/p>\n\u003cdetails class=\"project-setup\" id=\"project-setup\">\u003csummary>Starting setup \u003cspan id=\"setup-summary\">\u003c/span>\u003c/summary>\u003cdiv>\u003cp>Set the values supplied before your code starts. Apply setup ends the current run; the next build starts a fresh machine.\u003c/p>\u003cp id=\"lesson-setup-note\" hidden>Apply setup opens a project copy with these values. Your lesson draft and its starting setup stay unchanged.\u003c/p>\u003cform id=\"setup-form\">\u003cfieldset id=\"fragment-setup\">\u003cdiv class=\"setup-fields\">\u003clabel>Starting registers\u003ctextarea id=\"project-inputs\" rows=\"3\" aria-describedby=\"project-input-help\" placeholder=\"t0 = 7\nt1 = 5\" spellcheck=\"false\">\u003c/textarea>\u003c/label>\u003clabel>Data bytes at lesson_data\u003ctextarea id=\"project-bytes\" rows=\"3\" aria-describedby=\"project-data-help\" placeholder=\"01 02 03 04\" spellcheck=\"false\">\u003c/textarea>\u003c/label>\u003c/div>\u003cp id=\"project-input-help\">Use one assignment per line, such as t0 = 7. Decimal is the default; use 0x for hexadecimal or 0b for binary. Values must fit 64 bits. The starting setup does not accept zero, sp, gp or tp. The supplied code prepares the stack pointer; zero always reads zero.\u003c/p>\u003cp id=\"project-data-help\">Use pairs of hexadecimal digits separated by spaces, such as 01 FF. Up to 64 bytes; remaining bytes start at zero.\u003c/p>\u003c/fieldset>\u003cp id=\"full-program-help\" hidden>A complete assembly program supplies its own initialisation and data. Set those values in the source.\u003c/p>\u003cdiv class=\"setup-choices\">\u003clabel>Memory view\u003cselect id=\"project-memory\">\u003coption value=\"data\">Data bytes\u003c/option>\u003coption value=\"stack\">Stack bytes\u003c/option>\u003c/select>\u003c/label>\u003clabel>Highlighted register\u003cselect id=\"project-result\">\u003coption value=\"zero\">zero\u003c/option>\u003coption value=\"ra\">ra\u003c/option>\u003coption value=\"sp\">sp\u003c/option>\u003coption value=\"gp\">gp\u003c/option>\u003coption value=\"tp\">tp\u003c/option>\u003coption value=\"t0\">t0\u003c/option>\u003coption value=\"t1\">t1\u003c/option>\u003coption value=\"t2\">t2\u003c/option>\u003coption value=\"s0\">s0\u003c/option>\u003coption value=\"s1\">s1\u003c/option>\u003coption value=\"a0\">a0\u003c/option>\u003coption value=\"a1\">a1\u003c/option>\u003coption value=\"a2\">a2\u003c/option>\u003coption value=\"a3\">a3\u003c/option>\u003coption value=\"a4\">a4\u003c/option>\u003coption value=\"a5\">a5\u003c/option>\u003coption value=\"a6\">a6\u003c/option>\u003coption value=\"a7\">a7\u003c/option>\u003coption value=\"s2\">s2\u003c/option>\u003coption value=\"s3\">s3\u003c/option>\u003coption value=\"s4\">s4\u003c/option>\u003coption value=\"s5\">s5\u003c/option>\u003coption value=\"s6\">s6\u003c/option>\u003coption value=\"s7\">s7\u003c/option>\u003coption value=\"s8\">s8\u003c/option>\u003coption value=\"s9\">s9\u003c/option>\u003coption value=\"s10\">s10\u003c/option>\u003coption value=\"s11\">s11\u003c/option>\u003coption value=\"t3\">t3\u003c/option>\u003coption value=\"t4\">t4\u003c/option>\u003coption value=\"t5\">t5\u003c/option>\u003coption value=\"t6\">t6\u003c/option>\u003c/select>\u003c/label>\u003cbutton type=\"submit\">Apply setup\u003c/button>\u003c/div>\u003cp id=\"setup-memory-help\">Data shows 64 bytes from lesson_data. Stack shows 64 bytes from the observed stack pointer, sp. Marks a register in the inspector. It does not change execution.\u003c/p>\u003cp id=\"setup-error\" class=\"project-error\" role=\"status\">\u003c/p>\u003c/form>\u003c/div>\u003c/details>\n\u003cdetails id=\"complete-program-guide\" class=\"playground-help complete-program-guide\">\u003csummary>From a fragment to a complete program\u003c/summary>\u003cdiv>\u003cp>A fragment uses supplied setup and exit code. A complete program makes those choices in its own source.\u003c/p>\u003cp>\u003cstrong>Preparation.\u003c/strong> This example combines memory loads, a helper call and an xv6 exit. Use these lessons if those operations are new.\u003c/p>\u003cul>\u003cli>\u003ca href=\"../lessons/array-addresses/\">Array addresses and memory loads\u003c/a>\u003c/li>\u003cli>\u003ca href=\"../lessons/calls-and-returns/\">Calls and returns\u003c/a>\u003c/li>\u003cli>\u003ca href=\"../lessons/system-calls/\">xv6 system calls\u003c/a>\u003c/li>\u003cli>\u003ca href=\"../lessons/elf-entry/\">Executable entry\u003c/a>\u003c/li>\u003c/ul>\u003ch2>Own the inputs and exit\u003c/h2>\u003cp>The worked program stores two counts in its data section. _start loads them into a0 and a1, then calls combine.\u003c/p>\u003cp>The label _start names the program’s entry. The .data section defines its count values; no Starting setup values are added.\u003c/p>\n\u003cp>combine puts its result in a0. ret returns to the instruction after the call. The caller copies that value into s0 before using a0 for exit.\u003c/p>\n\u003cp>The exit request puts zero in a0 and the xv6 exit number in a7. Its ecall enters xv6 to finish the process. This program has no supplied reporter.\u003c/p>\u003cbutton id=\"open-worked-counts\">Open worked program\u003c/button>\u003col>\u003cli>Open the worked program as a new project. Your existing project is kept.\u003c/li>\u003cli>Select the line number beside the exit ecall to set a breakpoint. Choose Start debugging.\u003c/li>\u003cli>At that pause, inspect s0 and the data bytes. Explain how each loaded count reached the helper and how the result reached s0.\u003c/li>\u003cli>Choose Continue to let the exit call complete. The retained observations describe the last pause, not the exit state.\u003c/li>\u003c/ol>\u003ch2>Apply it to a different calculation\u003c/h2>\u003cp>The fresh project stores 31 and 17. Change combine to return the first count minus the second. Keep the result in s0 before exit.\u003c/p>\u003cp>Predict s0 before running. Set a breakpoint at the exit ecall and inspect the actual observation.\u003c/p>\u003cbutton id=\"open-fresh-counts\">Open fresh application\u003c/button>\u003cul>\u003cli>Which source defines the starting counts, and which instructions load them?\u003c/li>\u003cli>Where does call transfer control, and where does ret return?\u003c/li>\u003cli>Why is the returned result copied before a0 is prepared for exit?\u003c/li>\u003cli>Which pause supports your claimed result, and what does that observation leave unknown about exit?\u003c/li>\u003c/ul>\u003cp>Check your explanation against the source and paused machine. A matching number alone does not explain the input, call and exit boundaries.\u003c/p>\u003c/div>\u003c/details>\n\u003cdetails id=\"playground-help\" class=\"playground-help\">\u003csummary>Using the playground\u003c/summary>\u003cdiv>\u003csection>\u003ch2>Source and execution\u003c/h2>\u003cp>The editor and run controls work the same way in lessons and independent projects. Open Tools when you need more inspection, starting setup or saved projects. Close Tools to concentrate on the code and its relevant results.\u003c/p>\n\u003cp>Program shows your current source inside its complete program. Expand a supplied section to inspect the setup, capture or reporting code. Your fragment stays editable in the editor.\u003c/p>\n\u003cp>Machine instructions shows the executable from your last successful build. Build again after editing the source. During stepping, PC marks the next instruction to execute.\u003c/p>\n\u003cp>Registers shows observations from execution. Pin useful registers, compare changed values, or choose All to see every integer register.\u003c/p>\u003c/section>\u003csection>\u003ch2>Choose the source you want to write\u003c/h2>\u003cp>An assembly fragment is a group of instructions inside a supplied program. You can concentrate on those instructions; View complete program shows the entry, reporting and exit code around them.\u003c/p>\n\u003cp>A C project defines a function named lesson, such as long lesson(long a, long b). The supplied caller passes a0 and a1 as its arguments and captures the return value in a0. Do not add main, system headers or library calls.\u003c/p>\n\u003cp>A complete assembly program defines _start and includes its own exit code. Its registers and data come from its source and xv6, so the fragment’s starting-register and data controls do not apply.\u003c/p>\u003c/section>\u003csection>\u003ch2>Run and inspect\u003c/h2>\u003cp>Build &amp; Run assembles and links your source, then runs it as an xv6 user process. C projects first compile their function with TinyCC. Every new run starts a fresh machine.\u003c/p>\n\u003cp>Start stepping pauses before your first machine instruction. Step instruction executes one machine instruction. A source line can expand into several machine instructions.\u003c/p>\n\u003cp>A breakpoint pauses before its instruction runs. Choose the numbered button beside an assembly instruction, then use Start debugging. Continue runs to a selected breakpoint or the end of your code. For C, select actual instruction addresses in Debugger; this compiler does not provide C source-line mappings.\u003c/p>\n\u003cp>Register and memory readings belong to the observation named beside them. Assembly fragments and C functions capture a report after their code. Complete programs can exit without that report: a last paused observation is not an exit state.\u003c/p>\u003c/section>\u003csection>\u003ch2>Supply starting values\u003c/h2>\u003cp>For fragments and C functions, Setup supplies register values before your source runs. Use assignments such as t0 = 7, one per line. Apply setup commits the entries and ends the current run. Editing the setup form alone does not change a paused machine.\u003c/p>\n\u003cp>Data bytes fills the area named lesson_data. Hexadecimal uses digits 0–9 and A–F; two hexadecimal digits describe one byte. Unspecified bytes start at zero.\u003c/p>\n\u003cp>Memory view chooses the 64-byte region shown in Memory. Data starts at lesson_data. Stack starts at the observed stack pointer, sp. The Stack tab and memory watches provide further observed readings.\u003c/p>\u003c/section>\u003csection>\u003ch2>Keep your projects\u003c/h2>\u003cp>Source and setup save together in this browser when storage is available. Check the save message. A project saves your code and setup, not a running or paused machine.\u003c/p>\n\u003cp>Open Tools → Projects to open a saved project, choose an example, import a file or create a new project. Open example and Import file create new projects and keep your other work. Save a copy keeps the current source and setup in another project.\u003c/p>\n\u003cp>From a lesson, Save a copy opens an independent project in the same editor. The lesson draft stays available through Return to lesson. An exercise copy uses the selected case’s inputs and data.\u003c/p>\n\u003cp>Export project saves the source and setup in one JSON file. Download code saves only the source. Import file accepts project JSON, assembly source (.s or .asm), or C source (.c). Check Import as before opening a source file.\u003c/p>\n\u003cp>If storage is unavailable, you can keep working in this tab. Export project before leaving to keep that work. Delete project can be reversed with Undo delete.\u003c/p>\u003c/section>\u003csection>\u003ch2>Know the execution environment\u003c/h2>\u003cp>Programs target 64-bit RISC-V and run in xv6. Its system calls differ from Linux and teaching simulators. In this guest, write is system call 16 and exit is system call 2.\u003c/p>\n\u003cp>The playground supplies console output, but no console input. The guest does not provide floating-point process state. Stepping shows functional execution, not physical hardware timing.\u003c/p>\u003c/section>\u003cp>\u003ca href=\"../NOTICE.md\">Sources and licences\u003c/a> · \u003ca href=\"../using-the-workbench/\">Using the workbench\u003c/a>\u003c/p>\u003c/div>\u003c/details>\n\u003cdialog id=\"new-project-dialog\" aria-labelledby=\"new-project-heading\">\u003cform id=\"new-project-form\">\u003ch2 id=\"new-project-heading\">New project\u003c/h2>\u003clabel>Project name\u003cinput id=\"new-project-name\" value=\"Untitled project\" maxlength=\"80\" required>\u003c/label>\u003clabel>Project type\u003cselect id=\"new-project-kind\">\u003coption value=\"asm\">Assembly fragment\u003c/option>\u003coption value=\"c\">C function\u003c/option>\u003coption value=\"program\">Complete assembly program\u003c/option>\u003c/select>\u003c/label>\u003cp id=\"new-project-description\">\u003c/p>\u003cp id=\"new-project-error\" class=\"project-error\" role=\"status\">\u003c/p>\u003cdiv class=\"dialog-actions\">\u003cbutton type=\"button\" data-close-dialog>Cancel\u003c/button>\u003cbutton type=\"submit\" class=\"primary\">Create project\u003c/button>\u003c/div>\u003c/form>\u003c/dialog>\n\u003cdialog id=\"import-project-dialog\" aria-labelledby=\"import-heading\">\u003cform id=\"import-project-form\">\u003ch2 id=\"import-heading\">Import file\u003c/h2>\u003clabel>Project name\u003cinput id=\"import-project-name\" maxlength=\"80\" required>\u003c/label>\u003clabel>Import as\u003cselect id=\"import-project-kind\">\u003coption value=\"asm\">Assembly fragment\u003c/option>\u003coption value=\"c\">C function\u003c/option>\u003coption value=\"program\">Complete assembly program\u003c/option>\u003c/select>\u003c/label>\u003cpre id=\"import-preview\" tabindex=\"0\" aria-label=\"Source preview\">\u003c/pre>\u003cp id=\"import-error\" class=\"project-error\" role=\"status\">\u003c/p>\u003cdiv class=\"dialog-actions\">\u003cbutton type=\"button\" data-close-dialog>Cancel\u003c/button>\u003cbutton type=\"submit\" class=\"primary\">Open imported project\u003c/button>\u003c/div>\u003c/form>\u003c/dialog>\n"};
